import { createContext, useContext, useState, ReactNode } from 'react';
import { layoutItems } from '../constants/data';

interface DesignerState {
  isLive: boolean;
  publicView: 'modern' | 'simple';
  accentColor: string;
  primaryColor: string;
  fontFamily: string;
  sectionVisibility: Record<string, boolean>;
  language: string;
}

interface DesignerContextType {
  state: DesignerState;
  setIsLive: (val: boolean) => void;
  setPublicView: (val: 'modern' | 'simple') => void;
  setAccentColor: (val: string) => void;
  setPrimaryColor: (val: string) => void;
  setFontFamily: (val: string) => void;
  toggleSection: (id: string) => void;
  setSectionVisibility: (id: string, visible: boolean) => void;
  setLanguage: (val: string) => void;
}

const DesignerContext = createContext<DesignerContextType | null>(null);

const defaultVisibility: Record<string, boolean> = {};
layoutItems.forEach((item) => {
  defaultVisibility[item.id] = item.defaultEnabled;
});

export function DesignerProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<DesignerState>({
    isLive: true,
    publicView: 'modern',
    accentColor: '#DEE7EE',
    primaryColor: '#DEE7EE',
    fontFamily: '',
    sectionVisibility: defaultVisibility,
    language: 'English (US)',
  });

  const setIsLive = (val: boolean) => setState((s) => ({ ...s, isLive: val }));
  const setPublicView = (val: 'modern' | 'simple') => setState((s) => ({ ...s, publicView: val }));
  const setAccentColor = (val: string) => setState((s) => ({ ...s, accentColor: val }));
  const setPrimaryColor = (val: string) => setState((s) => ({ ...s, primaryColor: val }));
  const setFontFamily = (val: string) => setState((s) => ({ ...s, fontFamily: val }));
  const setLanguage = (val: string) => setState((s) => ({ ...s, language: val }));

  const toggleSection = (id: string) =>
    setState((s) => ({
      ...s,
      sectionVisibility: { ...s.sectionVisibility, [id]: !s.sectionVisibility[id] },
    }));

  const setSectionVisibility = (id: string, visible: boolean) =>
    setState((s) => ({
      ...s,
      sectionVisibility: { ...s.sectionVisibility, [id]: visible },
    }));

  return (
    <DesignerContext.Provider
      value={{
        state,
        setIsLive,
        setPublicView,
        setAccentColor,
        setPrimaryColor,
        setFontFamily,
        toggleSection,
        setSectionVisibility,
        setLanguage,
      }}
    >
      {children}
    </DesignerContext.Provider>
  );
}

export function useDesigner() {
  const ctx = useContext(DesignerContext);
  if (!ctx) throw new Error('useDesigner must be used within DesignerProvider');
  return ctx;
}

import { useState } from 'react';
import {
  Search,
  BarChart2,
  Bot,
  MessageSquare,
  FileText,
  ChevronDown,
  ChevronRight,
  Palette,
  Users,
  ExternalLink,
  HelpCircle,
  Bell,
  Gift,
  X,
  ArrowRight,
  PanelLeftClose,
  PanelLeftOpen,
} from 'lucide-react';

interface LeftNavProps {
  collapsed: boolean;
  onToggleCollapse: () => void;
}

export default function LeftNav({ collapsed, onToggleCollapse }: LeftNavProps) {
  const [expandedSpaces, setExpandedSpaces] = useState({
    securityQuestionnaires: true,
    rfxs: true,
    trustCenter: true,
  });

  const toggleSpace = (key: keyof typeof expandedSpaces) => {
    setExpandedSpaces((s) => ({ ...s, [key]: !s[key] }));
  };

  if (collapsed) {
    return (
      <div className="w-[48px] h-screen bg-white border-r border-primary-400 flex flex-col items-center py-3 shrink-0">
        <button
          onClick={onToggleCollapse}
          className="p-2 rounded hover:bg-primary-300 text-primary-700 mb-4"
        >
          <PanelLeftOpen size={16} />
        </button>
        <div className="flex flex-col gap-3 items-center mt-2">
          <div className="w-5 h-5 bg-purple-400 rounded-sm flex items-center justify-center">
            <span className="text-white text-[10px] font-medium">M</span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="w-[240px] h-screen bg-white border-r border-primary-400 flex flex-col shrink-0">
      {/* Org header */}
      <div className="px-2 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2 px-2 rounded hover:bg-primary-300 py-1 cursor-pointer">
          <div className="w-5 h-5 bg-purple-600 rounded-sm flex items-center justify-center overflow-hidden">
            <span className="text-white text-[10px] font-medium">M</span>
          </div>
          <span className="text-sm font-medium text-primary-800">Mediacore</span>
          <ChevronDown size={14} className="text-primary-800" />
        </div>
        <button
          onClick={onToggleCollapse}
          className="p-1.5 rounded hover:bg-primary-300 text-primary-600"
        >
          <PanelLeftClose size={14} />
        </button>
      </div>

      {/* Search */}
      <div className="px-3 pb-2">
        <div className="flex items-center gap-2 px-2.5 py-1.5 bg-primary-100 border border-primary-400 rounded-md text-primary-600 text-xs">
          <Search size={12} />
          <span>Get an answer (⌘K)</span>
        </div>
      </div>

      {/* Main nav */}
      <nav className="flex-1 overflow-y-auto px-1.5">
        <div className="space-y-0.5 mb-1">
          <NavItem icon={<BarChart2 size={14} />} label="Dashboard" />
          <NavItem icon={<Bot size={14} />} label="AI Agent Library" />
        </div>

        <NavSection title="Knowledge">
          <NavItem icon={<MessageSquare size={14} />} label="Knowledge Base" />
          <NavItem icon={<FileText size={14} />} label="Documents" />
        </NavSection>

        <NavSection title="Spaces">
          <div>
            <button
              onClick={() => toggleSpace('securityQuestionnaires')}
              className="flex items-center gap-1 w-full"
            >
              <div className="w-2 h-2 rounded-full bg-purple-400 ml-2 mr-1" />
              <span className="text-xs text-primary-800 font-medium">Security Questionnaires</span>
              <ChevronDown size={10} className="text-primary-600 ml-0.5" />
            </button>
            {expandedSpaces.securityQuestionnaires && (
              <div className="ml-5 mt-0.5">
                <SubNavItem label="Workspace" />
              </div>
            )}
          </div>

          <div className="mt-1">
            <button
              onClick={() => toggleSpace('rfxs')}
              className="flex items-center gap-1 w-full"
            >
              <div className="w-2 h-2 rounded-full bg-purple-400 ml-2 mr-1" />
              <span className="text-xs text-primary-800 font-medium">RFxs</span>
              <ChevronDown size={10} className="text-primary-600 ml-0.5" />
            </button>
            {expandedSpaces.rfxs && (
              <div className="ml-5 mt-0.5">
                <SubNavItem label="Projects" />
              </div>
            )}
          </div>

          <div className="mt-1">
            <button
              onClick={() => toggleSpace('trustCenter')}
              className="flex items-center gap-1 w-full"
            >
              <div className="w-2 h-2 rounded-full bg-purple-400 ml-2 mr-1" />
              <span className="text-xs text-primary-800 font-medium">Trust Center</span>
              <ChevronDown size={10} className="text-primary-600 ml-0.5" />
            </button>
            {expandedSpaces.trustCenter && (
              <div className="ml-5 mt-0.5 space-y-0.5">
                <SubNavItem label="Designer" active />
                <SubNavItem label="Audience" icon={<Users size={12} />} />
                <SubNavItem label="Preview" icon={<ExternalLink size={12} />} />
              </div>
            )}
          </div>
        </NavSection>
      </nav>

      {/* Promo banner */}
      <PromoBanner />

      {/* Bottom bar */}
      <div className="px-3 py-2 border-t border-primary-400 flex items-center justify-between">
        <button className="w-8 h-8 rounded-full border border-primary-500 flex items-center justify-center text-primary-700 hover:bg-primary-300">
          <HelpCircle size={14} />
        </button>
        <button className="px-3 py-1.5 rounded-full border border-primary-500 text-xs text-primary-800 font-medium hover:bg-primary-300">
          What's New
        </button>
        <button className="relative w-8 h-8 rounded-full border border-primary-500 flex items-center justify-center text-primary-700 hover:bg-primary-300">
          <Bell size={14} />
          <span className="absolute -top-1 -right-1 w-4 h-4 bg-failure-400 rounded-full text-white text-[9px] font-medium flex items-center justify-center">
            1
          </span>
        </button>
      </div>
    </div>
  );
}

function NavSection({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="mt-3 mb-1">
      <p className="px-3 text-[11px] font-medium text-primary-600 uppercase tracking-wide mb-1">
        {title}
      </p>
      <div className="space-y-0.5">{children}</div>
    </div>
  );
}

function NavItem({ icon, label, active }: { icon: React.ReactNode; label: string; active?: boolean }) {
  return (
    <button
      className={`flex items-center gap-2.5 w-full px-3 py-1.5 rounded-md text-xs transition-colors ${
        active ? 'bg-link-100 text-link-400 font-medium' : 'text-primary-800 hover:bg-primary-300'
      }`}
    >
      <span className={active ? 'text-link-400' : 'text-primary-700'}>{icon}</span>
      {label}
    </button>
  );
}

function SubNavItem({
  label,
  active,
  icon,
}: {
  label: string;
  active?: boolean;
  icon?: React.ReactNode;
}) {
  return (
    <button
      className={`flex items-center gap-2 w-full px-3 py-1.5 rounded-md text-xs transition-colors ${
        active ? 'bg-link-100 text-link-400 font-medium' : 'text-primary-800 hover:bg-primary-300'
      }`}
    >
      {icon ? (
        <span className={active ? 'text-link-400' : 'text-primary-700'}>{icon}</span>
      ) : (
        <ChevronRight size={10} className="text-primary-600" />
      )}
      {active && <Palette size={12} className="text-link-400" />}
      {label}
      {label === 'Preview' && <ExternalLink size={10} className="text-primary-600 ml-auto" />}
    </button>
  );
}

function PromoBanner() {
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;

  return (
    <div className="mx-3 mb-2 p-2 rounded-md relative overflow-hidden" style={{
      background: 'linear-gradient(33deg, rgba(51,198,159,0.25) 7%, rgba(118,186,249,0.25) 66%, rgba(200,179,232,0.25) 84%), white',
    }}>
      <button
        onClick={() => setDismissed(true)}
        className="absolute top-1 right-1 text-primary-600 hover:text-primary-800"
      >
        <X size={12} />
      </button>
      <Gift size={14} className="text-primary-800 mb-1" />
      <p className="text-[11px] font-medium text-primary-800">
        Give Conveyor, get an Airpod Max!
      </p>
      <button className="flex items-center gap-1 text-[11px] font-medium text-link-400 mt-0.5">
        Learn More <ArrowRight size={10} />
      </button>
    </div>
  );
}

