  HelpCircle,
  Bell,
  Gift,
  X,
  ArrowRight,
  PanelLeftClose,
  PanelLeftOpen,
} from 'lucide-react';

interface LeftNavProps {
  collapsed: boolean;
  onToggleCollapse: () => void;
}

export default function LeftNav({ collapsed, onToggleCollapse }: LeftNavProps) {
  const [expandedSpaces, setExpandedSpaces] = useState({
    securityQuestionnaires: true,
    rfxs: true,
    trustCenter: true,
  });

  const toggleSpace = (key: keyof typeof expandedSpaces) => {
    setExpandedSpaces((s) => ({ ...s, [key]: !s[key] }));
  };

  if (collapsed) {
    return (
      <div className="w-[48px] h-screen bg-bg-default border-r border-primary-400 flex flex-col items-center py-3 shrink-0">
        <button
          onClick={onToggleCollapse}
          className="p-2 rounded hover:bg-primary-300 text-primary-700 mb-4"
        >
          <PanelLeftOpen size={16} />
        </button>
        <div className="flex flex-col gap-3 items-center mt-2">
          <img
            src={uiAssets.mediacoreLogo}
            alt="Mediacore"
            className="w-5 h-5 rounded-sm object-cover"
          />
        </div>
      </div>
    );
  }

  return (
    <div className="w-[240px] h-screen bg-bg-default border-r border-primary-400 flex flex-col shrink-0">
      <div className="px-2 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2 px-2 rounded hover:bg-primary-300 py-1 cursor-pointer">
          <img
            src={uiAssets.mediacoreLogo}
            alt="Mediacore"
            className="w-5 h-5 rounded-sm object-cover"
          />
          <span className="text-sm font-medium text-primary-800">Mediacore</span>
          <ChevronDown size={14} className="text-primary-800" />
        </div>
        <button
          onClick={onToggleCollapse}
          className="p-1.5 rounded hover:bg-primary-300 text-primary-600"
        >
          <PanelLeftClose size={14} />
        </button>
      </div>

      <div className="px-3 pb-2">
        <div className="flex items-center gap-2 px-2.5 py-1.5 bg-primary-100 border border-primary-400 rounded-md text-primary-600 text-xs">
          <img src={icons.topbarSearch} alt="" className="w-3 h-3 opacity-60" />
          <span>Get an answer (⌘K)</span>
        </div>
      </div>

      <nav className="flex-1 overflow-y-auto px-1.5">
        <div className="space-y-0.5 mb-1">
          <NavItem icon={<img src={icons.navDashboard} alt="" className="w-[14px] h-[14px]" />} label="Dashboard" />
          <NavItem icon={<img src={icons.navAiAgent} alt="" className="w-[14px] h-[14px]" />} label="AI Agent Library" />
        </div>

        <NavSection title="Knowledge">
          <NavItem icon={<img src={icons.navKnowledgeBase} alt="" className="w-[14px] h-[14px]" />} label="Knowledge Base" />
          <NavItem icon={<img src={icons.navDocuments} alt="" className="w-[14px] h-[14px]" />} label="Documents" />
        </NavSection>

        <NavSection title="Spaces">
          <div>
            <button
              onClick={() => toggleSpace('securityQuestionnaires')}
              className="flex items-center gap-1 w-full"
            >
              <div className="w-2 h-2 rounded-full bg-purple-400 ml-2 mr-1" />
              <span className="text-xs text-primary-800 font-medium">Security Questionnaires</span>
              <ChevronDown size={10} className="text-primary-600 ml-0.5" />
            </button>
            {expandedSpaces.securityQuestionnaires && (
              <div className="ml-5 mt-0.5">
                <SubNavItem icon={<img src={icons.navWorkspace} alt="" className="w-3 h-3" />} label="Workspace" />
              </div>
            )}
          </div>

          <div className="mt-1">
            <button
              onClick={() => toggleSpace('rfxs')}
              className="flex items-center gap-1 w-full"
            >
              <div className="w-2 h-2 rounded-full bg-purple-400 ml-2 mr-1" />
              <span className="text-xs text-primary-800 font-medium">RFxs</span>
              <ChevronDown size={10} className="text-primary-600 ml-0.5" />
            </button>
            {expandedSpaces.rfxs && (
              <div className="ml-5 mt-0.5">
                <SubNavItem icon={<img src={icons.navProjects} alt="" className="w-3 h-3" />} label="Projects" />
              </div>
            )}
          </div>

          <div className="mt-1">
            <button
              onClick={() => toggleSpace('trustCenter')}
              className="flex items-center gap-1 w-full"
            >
              <div className="w-2 h-2 rounded-full bg-purple-400 ml-2 mr-1" />
              <span className="text-xs text-primary-800 font-medium">Trust Center</span>
              <ChevronDown size={10} className="text-primary-600 ml-0.5" />
            </button>
            {expandedSpaces.trustCenter && (
              <div className="ml-5 mt-0.5 space-y-0.5">
                <SubNavItem icon={<img src={icons.navDesigner} alt="" className="w-3 h-3" />} label="Designer" active />
                <SubNavItem icon={<img src={icons.navAudience} alt="" className="w-3 h-3" />} label="Audience" />
                <SubNavItem icon={<img src={icons.navPreview} alt="" className="w-3 h-3" />} label="Preview" hasExternal />
              </div>
            )}
          </div>
        </NavSection>
      </nav>

      <PromoBanner />

      <div className="px-3 py-2 border-t border-primary-400 flex items-center justify-between">
        <button className="w-8 h-8 rounded-full border border-primary-500 flex items-center justify-center text-primary-700 hover:bg-primary-300">
          <HelpCircle size={14} />
        </button>
        <button className="px-3 py-1.5 rounded-full border border-primary-500 text-xs text-primary-800 font-medium hover:bg-primary-300">
