    <div className="mt-3 mb-1">
      <p className="px-3 text-[11px] font-medium text-primary-600 uppercase tracking-wide mb-1">
        {title}
      </p>
      <div className="space-y-0.5">{children}</div>
    </div>
  );
}

function NavItem({ icon, label, active }: { icon: ReactNode; label: string; active?: boolean }) {
  return (
    <button
      className={`flex items-center gap-2.5 w-full px-3 py-1.5 rounded-md text-xs transition-colors ${
        active ? 'bg-link-100 text-link-400 font-medium' : 'text-primary-800 hover:bg-primary-300'
      }`}
    >
      <span className={`shrink-0 ${active ? 'text-link-400' : 'text-primary-700'}`}>{icon}</span>
      {label}
    </button>
  );
}

function SubNavItem({
  label,
  active,
  icon,
  hasExternal,
}: {
  label: string;
  active?: boolean;
  icon?: ReactNode;
  hasExternal?: boolean;
}) {
  return (
    <button
      className={`flex items-center gap-2 w-full px-3 py-1.5 rounded-md text-xs transition-colors ${
        active ? 'bg-link-100 text-link-400 font-medium' : 'text-primary-800 hover:bg-primary-300'
      }`}
    >
      {icon ? (
        <span className={`shrink-0 ${active ? 'text-link-400' : 'text-primary-700'}`}>{icon}</span>
      ) : (
        <ChevronRight size={10} className="text-primary-600" />
      )}
      {label}
      {hasExternal && (
        <img src={icons.navPreview} alt="" className="w-2.5 h-2.5 ml-auto opacity-60" />
      )}
    </button>
  );
}

function PromoBanner() {
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;

  return (
    <div className="mx-3 mb-2 p-2 rounded-md relative overflow-hidden" style={{
      background: 'linear-gradient(33deg, rgba(51,198,159,0.25) 7%, rgba(118,186,249,0.25) 66%, rgba(200,179,232,0.25) 84%), white',
    }}>
      <button
        onClick={() => setDismissed(true)}
        className="absolute top-1 right-1 text-primary-600 hover:text-primary-800"
      >
        <X size={12} />
      </button>
      <Gift size={14} className="text-primary-800 mb-1" />
      <p className="text-[11px] font-medium text-primary-800">
        Give Conveyor, get an Airpod Max!
