function LanguageDropdownTrigger() {
  const { state, setPreviewLocale } = useDesigner();
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, [open]);

  const activeLabel = previewLocaleLabel(state.previewLocale);

  return (
    <div ref={rootRef} className="relative border-b border-primary-400 bg-link-0 shrink-0 z-20">
      <button
        type="button"
        aria-expanded={open}
        aria-haspopup="listbox"
        onClick={() => setOpen((v) => !v)}
        className="h-[46px] px-5 w-full flex items-center justify-between gap-2 text-left hover:bg-link-100/60 transition-colors"
      >
        <div className="flex items-center gap-2 min-w-0">
          <MaterialIcon name="language" size={18} color="var(--color-primary-800)" className="shrink-0" />
          <span className="text-sm font-medium text-primary-800 truncate">{activeLabel}</span>
        </div>
        <ChevronDown
          size={16}
          strokeWidth={2}
          className={`text-primary-800 shrink-0 transition-transform ${open ? 'rotate-180' : ''}`}
          aria-hidden
        />
      </button>
      {open && (
        <div
          className="absolute left-0 right-0 top-full bg-white border-x border-b border-primary-400 shadow-lg z-30 py-1"
          role="listbox"
        >
          <div className="px-3 py-2 text-xs font-medium text-primary-600">Language</div>
          {LANGUAGE_MENU.map((item) => {
            const selected = state.previewLocale === item.locale;
            return (
              <button
                key={item.locale}
                type="button"
                role="option"
                aria-selected={selected}
                className={`w-full px-3 py-2.5 flex items-center justify-between gap-2 text-left transition-colors ${
                  selected ? 'bg-primary-100' : 'hover:bg-primary-200/80'
                }`}
                onClick={() => {
                  setPreviewLocale(item.locale);
                  setOpen(false);
                }}
              >
                <span className="text-sm font-medium text-primary-800">{item.label}</span>
                {item.live ? (
                  <span className="inline-flex items-center gap-1 rounded-full bg-brand-100 text-brand-600 px-2 py-0.5 text-[9px] font-bold tracking-wide shrink-0">
                    <span className="w-1.5 h-1.5 rounded-full bg-brand-400" aria-hidden />
                    LIVE
                  </span>
                ) : null}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

