import { useState } from 'react';
import { ChevronDown } from 'lucide-react';
import { productFilters, bigCards, documentsFaqTiles } from '../../constants/data';
import { useTrustCenterCopy } from '../../hooks/useTrustCenterCopy';
import MaterialIcon from '../MaterialIcon';
import badge1 from '../../assets/documents-faq-badges/badge-1.png';
import badge2Inner from '../../assets/documents-faq-badges/badge-2-inner.png';
import badge2Lock from '../../assets/documents-faq-badges/badge-2-lock.png';
import badge3 from '../../assets/documents-faq-badges/badge-3.png';
import badge4Eu from '../../assets/documents-faq-badges/badge-4-eu.png';

const CARD_SHADOW =
  '0px_1px_2px_0px_rgba(67,90,111,0.22),0px_0px_1px_0px_rgba(67,90,111,0.45)';
const TILE_ICON_COLOR = '#292951';

function DocumentComplianceBadges() {
  return (
    <div className="flex gap-0.5 flex-1 min-w-0 justify-start">
      <div className="w-8 h-8 rounded-[2px] bg-[#204f8c] flex items-center justify-center overflow-hidden shrink-0">
        <img src={badge1} alt="" className="w-[70%] h-[70%] object-contain" loading="lazy" decoding="async" />
      </div>
      <div className="w-8 h-8 rounded-[2px] bg-[#021f59] relative overflow-hidden shrink-0">
        <img
          src={badge2Inner}
          alt=""
          className="absolute inset-0 m-auto w-[55%] h-[55%] object-contain opacity-95"
          loading="lazy"
          decoding="async"
        />
        <img
          src={badge2Lock}
          alt=""
          className="absolute inset-0 m-auto w-[40%] h-[40%] object-contain translate-y-px"
          loading="lazy"
          decoding="async"
        />
      </div>
      <div className="w-8 h-8 rounded-[2px] bg-[#021f59] flex items-center justify-center overflow-hidden shrink-0">
        <img src={badge3} alt="" className="w-[70%] h-[70%] object-contain" loading="lazy" decoding="async" />
      </div>
      <div className="w-8 h-8 rounded-[2px] bg-[#204f8c] flex items-center justify-center overflow-hidden shrink-0">
        <img src={badge4Eu} alt="" className="w-[85%] h-[85%] object-contain" loading="lazy" decoding="async" />
      </div>
    </div>
  );
}

export default function DocumentsFAQsSection() {
  const [activeFilter, setActiveFilter] = useState('All Products');
  const copy = useTrustCenterCopy();

  return (
    <div className="px-10 py-8 flex flex-col gap-4">
      <h2
        className="text-base font-medium text-[#47687d] leading-[1.35] shrink-0"
        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
      >
        {copy.documentsFaqsTitle}
      </h2>

      <div className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center gap-2 min-h-[50px]">
          <span
            className="text-sm text-[#47687d] shrink-0 leading-[1.35]"
            style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 400 }}
          >
            {copy.reviewingLabel}
          </span>
          <div className="flex flex-wrap gap-1 items-center">
            {productFilters.map((filter) => {
              const isMore = filter.startsWith('+');
              const selected = activeFilter === filter;
              return (
                <button
                  key={filter}
                  type="button"
                  onClick={() => setActiveFilter(filter)}
                  className={`inline-flex items-center gap-2 rounded-2xl px-2 py-1.5 text-xs font-medium leading-[1.35] transition-colors border ${
                    selected
                      ? 'bg-[rgba(150,150,176,0.15)] border-[#292951] text-primary-800'
                      : 'bg-white border-primary-500 text-primary-700 hover:border-primary-600'
                  }`}
                  style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
                >
                  {filter}
                  {isMore ? <ChevronDown size={16} className="text-primary-700 shrink-0" strokeWidth={2} /> : null}
                </button>
              );
            })}
          </div>
        </div>

        <div className="flex flex-col gap-5">
          <div className="grid grid-cols-2 gap-5">
            {bigCards.map((card) => {
              const isDocs = card.title === 'Documents';
              const title = isDocs ? copy.documentsCardTitle : copy.knowledgeFaqsCardTitle;
              const showBadges = 'showComplianceBadges' in card ? card.showComplianceBadges : isDocs;
              return (
                <button
                  key={card.title}
                  type="button"
                  className="flex flex-col bg-white border border-primary-400 rounded-lg overflow-hidden text-left group hover:border-primary-500 transition-colors"
                  style={{ boxShadow: CARD_SHADOW.replace(/_/g, ' ') }}
                >
                  <div
                    className="h-2 w-full shrink-0"
                    style={{ backgroundColor: 'var(--trust-center-header-color, #2d2b55)' }}
                  />
                  <div className="p-5 flex flex-col gap-5">
                    <div className="flex items-center gap-2">
                      <span
                        className="text-base font-medium text-primary-800 leading-[1.35] whitespace-nowrap"
                        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
                      >
                        {title}
                      </span>
                      <div className="bg-primary-300 flex h-6 min-w-[24px] items-center justify-center px-2 rounded overflow-hidden shrink-0">
                        <span
                          className="text-sm font-medium text-primary-800 leading-[1.35]"
                          style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
                        >
                          {card.count}
                        </span>
                      </div>
                    </div>
                    <div className="flex items-center gap-5 w-full min-h-[40px]">
                      {showBadges ? (
                        <DocumentComplianceBadges />
                      ) : (
                        <div className="flex-1 min-h-[32px]" aria-hidden />
                      )}
                      <div
                        className="w-10 h-10 rounded-full flex items-center justify-center shrink-0 group-hover:opacity-90 transition-opacity"
                        style={{ backgroundColor: 'var(--trust-center-header-color, #2d2b55)' }}
                      >
                        <MaterialIcon name="arrow_forward" size={18} color="#ffffff" filled />
                      </div>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>

          <div className="flex flex-col gap-2">
            {Array.from({ length: Math.ceil(documentsFaqTiles.length / 3) }, (_, row) => (
              <div key={row} className="grid grid-cols-3 gap-2">
                {documentsFaqTiles.slice(row * 3, row * 3 + 3).map((doc) => (
                  <button
                    key={`${doc.name}-${row}-${doc.answers}`}
                    type="button"
                    className="flex items-center gap-4 p-3 bg-white border border-primary-400 rounded-lg hover:border-primary-500 transition-colors text-left min-h-[64px]"
                  >
                    <div
                      className="w-10 h-10 rounded-full flex items-center justify-center shrink-0"
                      style={{ backgroundColor: 'rgba(150, 150, 176, 0.15)' }}
                    >
                      <MaterialIcon name={doc.icon} size={18} color={TILE_ICON_COLOR} filled />
                    </div>
                    <div className="flex flex-col gap-1 min-w-0 justify-center">
                      <span
                        className="text-sm font-medium text-primary-800 leading-[1.35]"
                        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
                      >
                        {doc.name}
                      </span>
                      <span
                        className="text-xs text-[#47687d] leading-tight whitespace-nowrap"
                        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 400 }}
                      >
                        {doc.answers} {copy.answersSuffix}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

