}

/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_LOGO_DEV_TOKEN: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

/**
 * Logo.dev Image CDN — https://docs.logo.dev/introduction
 * Requires `VITE_LOGO_DEV_TOKEN` in `.env.local` (publishable key).
 */
export function getLogoDevImageSrc(domain: string, options?: { size?: number }): string | null {
  const token = import.meta.env.VITE_LOGO_DEV_TOKEN;
  const d = domain?.trim();
  if (!d || !token || typeof token !== 'string' || !token.trim()) return null;
  const size = options?.size ?? 128;
  return `https://img.logo.dev/${encodeURIComponent(d)}?token=${encodeURIComponent(token.trim())}&size=${size}`;
}

import { useMemo, useState, type CSSProperties } from 'react';
import { getLogoDevImageSrc } from '../lib/logoDev';

type LogoDevMarkProps = {
  /** Registered domain, e.g. `stripe.com` */
  domain: string;
  /** Display name — used for fallback initial and optional alt text */
  name: string;
  /** CSS box size in pixels */
  sizePx: number;
  className?: string;
  /** Classes for the letter fallback (when no token, bad domain, or image error) */
  fallbackClassName?: string;
  fallbackStyle?: CSSProperties;
  /** If set, used as img alt; otherwise `name` is used when showing the image */
  alt?: string;
};

export default function LogoDevMark({
  domain,
  name,
  sizePx,
  className = '',
  fallbackClassName = '',
  fallbackStyle,
  alt,
}: LogoDevMarkProps) {
  const src = useMemo(
    () => getLogoDevImageSrc(domain, { size: Math.min(512, Math.max(64, sizePx * 2)) }),
    [domain, sizePx],
  );
  const [failed, setFailed] = useState(false);
  const initial = (name.trim()[0] ?? '?').toUpperCase();

  if (!src || failed) {
    return (
      <div
        className={`flex shrink-0 items-center justify-center font-medium ${fallbackClassName}`}
        style={{ width: sizePx, height: sizePx, fontSize: Math.max(10, sizePx * 0.38), ...fallbackStyle }}
        aria-hidden
      >
        {initial}
      </div>
    );
  }

  return (
    <img
      src={src}
      alt={alt ?? `${name} logo`}
      width={sizePx}
      height={sizePx}
      className={`shrink-0 object-contain ${className}`}
      loading="lazy"
      decoding="async"
      onError={() => setFailed(true)}
    />
  );
}

