import { ChevronDown } from 'lucide-react';

const neue = { fontFamily: "'Neue Montreal', sans-serif" } as const;

export type ProductFilterChipsVariant = 'documents' | 'featured';

export type ProductFilterChipsProps = {
  /** e.g. copy.reviewingLabel — “I'm reviewing:” */
  label: string;
  filters: readonly string[];
  activeFilter: string;
  onFilterChange: (filter: string) => void;
  /** `documents` = Find an Answer bar (lavender selected, + More chevron). `featured` = Featured Documents purple pills. */
  variant?: ProductFilterChipsVariant;
  className?: string;
};

export default function ProductFilterChips({
  label,
  filters,
  activeFilter,
  onFilterChange,
  variant = 'documents',
  className,
}: ProductFilterChipsProps) {
  const isFeatured = variant === 'featured';

  return (
    <div
      className={
        isFeatured
          ? `mb-5 flex flex-wrap items-center gap-2 ${className ?? ''}`
          : `flex flex-wrap items-center gap-2 min-h-[50px] ${className ?? ''}`
      }
    >
      <span
        className={
          isFeatured
            ? 'shrink-0 text-sm font-medium leading-[1.35] text-primary-800'
            : 'shrink-0 text-sm leading-[1.35] text-[#47687d]'
        }
        style={{ ...neue, fontWeight: isFeatured ? 500 : 400 }}
      >
        {label}
      </span>
      <div className={`flex flex-wrap items-center ${isFeatured ? 'gap-2' : 'gap-1'}`}>
        {filters.map((filter) => {
          const selected = activeFilter === filter;
          const isMore = filter.startsWith('+');

          if (isFeatured) {
            return (
              <button
                key={filter}
