/** IDs for Trust Center sections that appear in “Customize Layout” (designer) and drive main-column order. */
export const LAYOUT_SECTION_IDS = [
  'badges',
  'documents',
  'knowledge-base-faqs',
  'philosophy',
  'quick-summary',
  'subprocessors',
  'trusted-by',
  'featured-documents',
  'announcements',
  'what-we-offer',
  'video-resources',
] as const;

export type LayoutSectionId = (typeof LAYOUT_SECTION_IDS)[number];

/** Default vertical order (Identity + banner stay fixed above this list). */
export const DEFAULT_SECTION_ORDER: LayoutSectionId[] = [...LAYOUT_SECTION_IDS];

/** Labels shown in the designer right panel — match Trust Center section titles. */
export const LAYOUT_SECTION_LABELS: Record<LayoutSectionId, string> = {
  badges: 'Certifications',
  documents: 'Documents',
  'knowledge-base-faqs': 'Knowledge Base FAQs',
  philosophy: 'Our philosophy',
  'quick-summary': 'Quick summary',
  subprocessors: 'Subprocessors',
  'trusted-by': 'Trusted by',
  'featured-documents': 'Featured Documents',
  announcements: 'Announcements',
  'what-we-offer': 'What we offer',
  'video-resources': 'Video resources',
};

export function isDocPairId(id: string): boolean {
  return id === 'documents' || id === 'knowledge-base-faqs';
}

/** Start index of the block containing `order[index]` (documents + FAQs move as one or two-slot block). */
export function blockStartAt(order: readonly string[], index: number): number {
  const id = order[index];
  if (!isDocPairId(id)) return index;
  if (id === 'knowledge-base-faqs' && order[index - 1] === 'documents') return index - 1;
  if (id === 'documents' && order[index - 1] === 'knowledge-base-faqs') return index - 1;
  return index;
}

export function blockLengthAt(order: readonly string[], start: number): number {
  const a = order[start];
  const b = order[start + 1];
  if (a === 'documents' && b === 'knowledge-base-faqs') return 2;
  if (a === 'knowledge-base-faqs' && b === 'documents') return 2;
  return 1;
}

/** If Documents and Knowledge Base FAQs are both present but not adjacent, reinsert them as a pair preserving relative order. */
export function ensureDocPairAdjacent(order: string[]): string[] {
  const d = order.indexOf('documents');
  const k = order.indexOf('knowledge-base-faqs');
  if (d === -1 || k === -1) return [...order];
  if (Math.abs(d - k) === 1) return [...order];
  const rest = order.filter((id) => id !== 'documents' && id !== 'knowledge-base-faqs');
  const insertAt = Math.min(d, k);
  const first = d < k ? 'documents' : 'knowledge-base-faqs';
  const second = d < k ? 'knowledge-base-faqs' : 'documents';
  rest.splice(insertAt, 0, first, second);
  return rest;
}

export function moveSectionBlock(order: readonly string[], dragIndex: number, dropIndex: number): string[] {
  const fromStart = blockStartAt(order, dragIndex);
  const len = blockLengthAt(order, fromStart);
  const toStart = blockStartAt(order, dropIndex);
  const next = [...order];
  const block = next.splice(fromStart, len);
  let insertAt = toStart;
  if (fromStart < toStart) insertAt -= len;
  insertAt = Math.max(0, Math.min(insertAt, next.length));
  next.splice(insertAt, 0, ...block);
  return ensureDocPairAdjacent(next);
}

