type RenderUnit = { type: 'doc-pair' } | { type: 'single'; id: LayoutSectionId };

function buildRenderPlan(order: readonly string[]): RenderUnit[] {
  const plan: RenderUnit[] = [];
  let i = 0;
  while (i < order.length) {
    const id = order[i];
    if (isDocPairId(id)) {
      plan.push({ type: 'doc-pair' });
      while (i < order.length && isDocPairId(order[i])) i++;
      continue;
    }
    if (LAYOUT_SECTION_IDS.includes(id as LayoutSectionId)) {
      plan.push({ type: 'single', id: id as LayoutSectionId });
    }
    i++;
  }
  return plan;
}

const LAYOUT_SECTION_IDS = DEFAULT_SECTION_ORDER;

function documentsColumnFirst(order: readonly string[]): boolean {
  const d = order.indexOf('documents');
  const k = order.indexOf('knowledge-base-faqs');
  if (d === -1 || k === -1) return true;
  return d < k;
}

interface TrustCenterContentProps {
  standalone?: boolean;
}

export default function TrustCenterContent({ standalone = false }: TrustCenterContentProps) {
  const { state } = useDesigner();
  const v = state.sectionVisibility;
  /** Public `/trust-center` ignores designer hide toggles so the page always shows full content. */
  const show = (id: string) => standalone || (v[id] ?? true);
  const sectionOrder = standalone ? [...DEFAULT_SECTION_ORDER] : state.sectionOrder;

  const onSectionClick = (sectionId: string) => {
    document.getElementById(sectionId)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const onDocumentClick = (_item: SearchItem) => {
    /* Prototype: document viewer not wired */
  };

  const onAskAI = (_query: string) => {
    /* Prototype: chat not wired */
  };

  const plan = buildRenderPlan(sectionOrder).filter((unit) => {
    if (unit.type === 'doc-pair') return show('documents') || show('knowledge-base-faqs');
    return show(unit.id);
  });

  const renderSingle = (id: LayoutSectionId) => {
    switch (id) {
      case 'badges':
        return <CertificationsSection />;
      case 'philosophy':
        return <PhilosophySection />;
      case 'quick-summary':
        return <QuickSummarySection />;
      case 'subprocessors':
        return <SubprocessorsSection />;
      case 'trusted-by':
        return <TrustedBySection />;
      case 'featured-documents':
        return <FeaturedDocumentsSection />;
      case 'announcements':
        return <AnnouncementsSection />;
      case 'what-we-offer':
        return <WhatWeOfferSection />;
      case 'video-resources':
        return <VideoSection />;
      default:
        return null;
    }
  };

  return (
    <ProductFilterProvider>
      <ReviewingProductFilterProvider>
        <div
          className={`min-w-0 bg-white ${standalone ? 'min-h-screen' : 'min-h-0 w-full flex-1 overflow-y-auto'}`}
        >
          <StickyNav
            onSectionClick={onSectionClick}
            onDocumentClick={onDocumentClick}
            onAskAI={onAskAI}
          />
          <div className={standalone ? 'max-w-[1360px] mx-auto' : ''}>
            <HeaderBanner />

            <div
              id="section-just-for-you"
              className="scroll-mt-20 h-px w-full max-w-[1360px] mx-auto shrink-0"
              aria-hidden
            />

            <IdentitySection />

            <Divider />

            {plan.map((unit, idx) => (
              <Fragment key={unit.type === 'doc-pair' ? 'doc-pair-block' : unit.id}>
                {unit.type === 'doc-pair' ? (
                  <DocumentsFAQsSection
                    showDocumentsTile={show('documents')}
                    showKnowledgeTile={show('knowledge-base-faqs')}
                    documentsColumnFirst={documentsColumnFirst(sectionOrder)}
                  />
                ) : (
                  renderSingle(unit.id)
                )}
                {idx < plan.length - 1 ? <Divider /> : null}
              </Fragment>
            ))}
          </div>
        </div>
      </ReviewingProductFilterProvider>
    </ProductFilterProvider>
  );
}

function Divider() {
  return <div className="mx-10 my-10 border-t border-primary-400" />;
}

