import { useTrustCenterCopy } from '../../hooks/useTrustCenterCopy';
import MaterialIcon from '../MaterialIcon';
import ProductFilterChips from './ProductFilterChips';

const CARD_SHADOW =
  '0px 1px 2px 0px rgba(67,90,111,0.22), 0px 0px 1px 0px rgba(67,90,111,0.45)';
const TILE_ICON_COLOR = '#292951';

/** First four badges from `src/assets/badges` (shared with Certifications section). */
const DOCUMENTS_CARD_BADGES = certifications.slice(0, 4);

function DocumentComplianceBadges() {
  return (
    <div className="flex gap-2 flex-1 min-w-0 justify-start items-center flex-wrap">
      {DOCUMENTS_CARD_BADGES.map((cert) => (
        <img
          key={cert.name}
          src={cert.image}
          alt=""
          className="h-8 w-8 max-h-8 max-w-8 shrink-0 object-contain"
          width={32}
          height={32}
          loading="lazy"
          decoding="async"
        />
      ))}
    </div>
  );
}

/** Documents + Knowledge Base FAQs big cards, FAQ topic tiles, and filters — one designer “find-answer” block. */
export default function DocumentsFAQsSection() {
  const { activeReviewingFilter, setActiveReviewingFilter } = useReviewingProductFilter();
  const copy = useTrustCenterCopy();

  return (
    <div id="section-find-answer" className="mx-10 py-8 flex flex-col gap-4 scroll-mt-20">
      <h2
        className="text-base font-medium text-[#47687d] leading-[1.35] shrink-0"
        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
      >
        {copy.documentsFaqsTitle}
      </h2>

      <div className="flex flex-col gap-4">
        <ProductFilterChips
          label={copy.reviewingLabel}
          filters={productFilters}
          activeFilter={activeReviewingFilter}
          onFilterChange={setActiveReviewingFilter}
        />

        <div className="flex flex-col gap-5">
          <div className="grid grid-cols-2 gap-5">
            {bigCards.map((card) => {
              const isDocs = card.title === 'Documents';
              const title = isDocs ? copy.documentsCardTitle : copy.knowledgeFaqsCardTitle;
              const showBadges = card.showComplianceBadges;
              return (
                <button
                  key={card.title}
                  id={isDocs ? 'section-documents' : 'section-knowledge-base-faqs'}
                  type="button"
                  className={`flex flex-col bg-white border border-primary-400 rounded-lg overflow-hidden text-left group hover:border-primary-500 transition-colors ${isDocs ? 'scroll-mt-20' : ''}`}
                  style={{ boxShadow: CARD_SHADOW }}
                >
                  <div
                    className="h-2 w-full shrink-0"
                    style={{ backgroundColor: 'var(--trust-center-header-color, #2d2b55)' }}
                  />
                  <div className="p-5 flex flex-col gap-5">
                    <div className="flex items-center gap-2">
                      <span
                        className="text-base font-medium text-primary-800 leading-[1.35] whitespace-nowrap"
                        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
                      >
                        {title}
                      </span>
                      <div className="bg-primary-300 flex h-6 min-w-[24px] items-center justify-center px-2 rounded overflow-hidden shrink-0">
                        <span
                          className="text-sm font-medium text-primary-800 leading-[1.35]"
                          style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
                        >
                          {card.count}
                        </span>
                      </div>
                    </div>
                    <div className="flex min-h-10 w-full items-center gap-5">
                      {showBadges ? (
                        <DocumentComplianceBadges />
                      ) : (
                        <div className="min-h-10 flex-1" aria-hidden />
                      )}
                      <div
                        className="w-10 h-10 rounded-full flex items-center justify-center shrink-0 group-hover:opacity-90 transition-opacity"
                        style={{ backgroundColor: 'var(--trust-center-header-color, #2d2b55)' }}
                      >
                        <MaterialIcon name="arrow_forward" size={18} color="#ffffff" filled />
                      </div>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>

          <div className="flex flex-col gap-2">
            {Array.from({ length: Math.ceil(documentsFaqTiles.length / 3) }, (_, row) => (
              <div key={row} className="grid grid-cols-3 gap-2">
                {documentsFaqTiles.slice(row * 3, row * 3 + 3).map((doc, col) => (
                  <button
                    key={`tile-${row * 3 + col}`}
                    type="button"
                    className="flex items-center gap-4 p-3 bg-white border border-primary-400 rounded-lg hover:border-primary-500 transition-colors text-left min-h-[64px]"
                  >
                    <div
                      className="w-10 h-10 rounded-full flex items-center justify-center shrink-0"
                      style={{ backgroundColor: 'rgba(150, 150, 176, 0.15)' }}
                    >
                      <MaterialIcon name={doc.icon} size={18} color={TILE_ICON_COLOR} filled />
                    </div>
                    <div className="flex flex-col gap-1 min-w-0 justify-center">
                      <span
                        className="text-sm font-medium text-primary-800 leading-[1.35]"
                        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 500 }}
                      >
                        {doc.name}
                      </span>
                      <span
                        className="text-xs text-[#47687d] leading-tight whitespace-nowrap"
                        style={{ fontFamily: "'Neue Montreal', sans-serif", fontWeight: 400 }}
                      >
                        {doc.answers} {copy.answersSuffix}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { Fragment } from 'react';
import { useDesigner } from '../../context/DesignerContext';
import { ProductFilterProvider } from '../../contexts/ProductFilterContext';
import { ReviewingProductFilterProvider } from '../../contexts/ReviewingProductFilterContext';
import {
  DEFAULT_SECTION_ORDER,
  LAYOUT_SECTION_IDS,
  type LayoutSectionId,
} from '../../constants/layoutSectionOrder';
import StickyNav from '../Navigation/StickyNav';
import type { SearchItem } from '../../data/searchData';
import HeaderBanner from './HeaderBanner';
import IdentitySection from './IdentitySection';
import CertificationsSection from './CertificationsSection';
import DocumentsFAQsSection from './DocumentsFAQsSection';
import PhilosophySection from './PhilosophySection';
import QuickSummarySection from './QuickSummarySection';
import SubprocessorsSection from './SubprocessorsSection';
import TrustedBySection from './TrustedBySection';
import FeaturedDocumentsSection from './FeaturedDocumentsSection';
import AnnouncementsSection from './AnnouncementsSection';
import WhatWeOfferSection from './WhatWeOfferSection';
import VideoSection from './VideoSection';

interface TrustCenterContentProps {
  standalone?: boolean;
}

function buildRenderPlan(order: readonly string[]): LayoutSectionId[] {
  return order.filter((id): id is LayoutSectionId =>
    (LAYOUT_SECTION_IDS as readonly string[]).includes(id),
  );
}

export default function TrustCenterContent({ standalone = false }: TrustCenterContentProps) {
  const { state } = useDesigner();
  const v = state.sectionVisibility;
  /** Public `/trust-center` ignores designer hide toggles so the page always shows full content. */
  const show = (id: string) => standalone || (v[id] ?? true);
  const sectionOrder = standalone ? [...DEFAULT_SECTION_ORDER] : state.sectionOrder;

  const onSectionClick = (sectionId: string) => {
    document.getElementById(sectionId)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const onDocumentClick = (_item: SearchItem) => {
    /* Prototype: document viewer not wired */
  };

  const onAskAI = (_query: string) => {
    /* Prototype: chat not wired */
  };

  const plan = buildRenderPlan(sectionOrder).filter((id) => show(id));

  const renderSection = (id: LayoutSectionId) => {
    switch (id) {
      case 'badges':
        return <CertificationsSection />;
      case 'find-answer':
        return <DocumentsFAQsSection />;
      case 'philosophy':
        return <PhilosophySection />;
      case 'quick-summary':
        return <QuickSummarySection />;
      case 'subprocessors':
        return <SubprocessorsSection />;
      case 'trusted-by':
        return <TrustedBySection />;
      case 'featured-documents':
        return <FeaturedDocumentsSection />;
      case 'announcements':
        return <AnnouncementsSection />;
      case 'what-we-offer':
        return <WhatWeOfferSection />;
      case 'video-resources':
        return <VideoSection />;
      default:
        return null;
    }
  };

  return (
    <ProductFilterProvider>
      <ReviewingProductFilterProvider>
        <div
          className={`min-w-0 bg-white ${standalone ? 'min-h-screen' : 'min-h-0 w-full flex-1 overflow-y-auto'}`}
        >
          <StickyNav
            onSectionClick={onSectionClick}
            onDocumentClick={onDocumentClick}
            onAskAI={onAskAI}
          />
          <div className={standalone ? 'max-w-[1360px] mx-auto' : ''}>
            <HeaderBanner />

            <div
              id="section-just-for-you"
              className="scroll-mt-20 h-px w-full max-w-[1360px] mx-auto shrink-0"
              aria-hidden
            />

            <IdentitySection />

            <Divider />

            {plan.map((id, idx) => (
              <Fragment key={id}>
                {renderSection(id)}
                {idx < plan.length - 1 ? <Divider /> : null}
              </Fragment>
            ))}
          </div>
        </div>
      </ReviewingProductFilterProvider>
    </ProductFilterProvider>
  );
}

function Divider() {
  return <div className="mx-10 my-10 border-t border-primary-400" />;
}

