import { createContext, useContext, type ReactNode } from 'react';

export type EditableTrustSectionId = 'banner' | 'profile' | 'badges';

export type TrustCenterSectionEditValue = {
  enabled: boolean;
  onSectionEdit: (id: EditableTrustSectionId) => void;
};

const TrustCenterSectionEditContext = createContext<TrustCenterSectionEditValue | null>(null);

export function TrustCenterSectionEditProvider({
  value,
  children,
}: {
  value: TrustCenterSectionEditValue;
  children: ReactNode;
}) {
  return (
    <TrustCenterSectionEditContext.Provider value={value}>{children}</TrustCenterSectionEditContext.Provider>
  );
}

export function useTrustCenterSectionEdit(): TrustCenterSectionEditValue {
  return (
    useContext(TrustCenterSectionEditContext) ?? {
      enabled: false,
      onSectionEdit: () => {},
    }
  );
}

import { faPencil } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import type { ReactNode } from 'react';
import type { EditableTrustSectionId } from '../../contexts/TrustCenterSectionEditContext';

const OVERLAY_BG = 'rgba(71, 104, 125, 0.15)';

const ARIA_LABELS: Record<EditableTrustSectionId, string> = {
  banner: 'Edit hero banner',
  profile: 'Edit profile and headline',
  badges: 'Edit certifications',
};

type Props = {
  sectionId: EditableTrustSectionId;
  enabled: boolean;
  onEditClick: (id: EditableTrustSectionId) => void;
  children: ReactNode;
  className?: string;
};

export default function TrustCenterEditableRegion({
  sectionId,
  enabled,
  onEditClick,
  children,
  className = '',
}: Props) {
  if (!enabled) {
    return <>{children}</>;
  }

  return (
    <div className={`relative isolate group/tc-edit ${className}`.trim()}>
      {children}
      <button
        type="button"
        className="absolute inset-0 z-10 flex cursor-pointer items-center justify-center opacity-0 pointer-events-none transition-opacity duration-150 motion-reduce:transition-none group-hover/tc-edit:opacity-100 group-hover/tc-edit:pointer-events-auto focus-visible:opacity-100 focus-visible:pointer-events-auto"
        style={{ backgroundColor: OVERLAY_BG }}
        onClick={() => onEditClick(sectionId)}
        aria-label={ARIA_LABELS[sectionId]}
      >
        <span className="rounded-full bg-white/95 p-3 shadow-md ring-1 ring-primary-400">
          <FontAwesomeIcon icon={faPencil} className="h-5 w-5 text-primary-800" aria-hidden />
        </span>
      </button>
    </div>
  );
}

import { useEffect } from 'react';
import type { EditableTrustSectionId } from '../../contexts/TrustCenterSectionEditContext';

const TITLES: Record<EditableTrustSectionId, string> = {
  banner: 'Edit hero banner',
  profile: 'Edit profile & headline',
  badges: 'Edit certifications',
};

type Props = {
  section: EditableTrustSectionId | null;
  onClose: () => void;
};

export default function EditSectionPlaceholderModal({ section, onClose }: Props) {
  useEffect(() => {
    if (!section) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [section, onClose]);

  if (!section) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
      <button
        type="button"
        className="absolute inset-0 bg-black/45"
        onClick={onClose}
        aria-label="Close dialog"
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="edit-section-modal-title"
        className="relative w-full max-w-md rounded-lg border border-primary-400 bg-white p-6 shadow-xl"
      >
        <h2
          id="edit-section-modal-title"
          className="text-base font-medium text-primary-800"
          style={{ fontFamily: "'Neue Montreal', sans-serif" }}
        >
          {TITLES[section]}
        </h2>
        <p className="mt-2 text-sm text-primary-600 leading-relaxed">
          Editor content will go here. Replace this modal when your designs are ready.
        </p>
        <div className="mt-6 flex justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className="rounded-md border border-primary-400 bg-white px-4 py-2 text-sm font-medium text-primary-800 hover:bg-primary-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-link-400"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

