import { useState } from 'react';
import { Link } from 'react-router-dom';
import { useDesigner } from '../../context/DesignerContext';
import TrustCenterModalBackdrop from '../TrustCenter/TrustCenterModalBackdrop';

/**
 * Designer shell: preview toggle, publish status, and quick publish above the Trust Center column.
 */
export default function DesignerStagingToolbar() {
  const { state, setPreviewMode, isActiveDraftDirty, publishActiveDraft } = useDesigner();
  const [publishOpen, setPublishOpen] = useState(false);

  return (
    <>
      <div className="z-[100] flex min-h-[3rem] shrink-0 flex-wrap items-center gap-3 border-b border-primary-400 bg-primary-100 px-6 py-2.5">
        <div className="min-w-0 flex-[1_1_10rem]">
          <p className="text-xs leading-snug text-primary-700">
            {isActiveDraftDirty ? (
              <>
                This draft has{' '}
                <span className="font-semibold text-primary-900">unpublished changes</span>—they are not on the live
                Trust Center until you publish.
              </>
            ) : (
              <>No unpublished changes in this draft; it matches the live Trust Center.</>
            )}
          </p>
        </div>

        <div className="flex shrink-0 justify-center">
          <div className="inline-flex rounded border border-primary-400 bg-white p-0.5">
            <button
              type="button"
              className={`rounded px-2.5 py-1 text-xs font-medium ${
                state.previewMode === 'draft' ? 'bg-primary-800 text-white' : 'text-primary-800 hover:bg-primary-100'
              }`}
              onClick={() => setPreviewMode('draft')}
            >
              Draft
            </button>
            <button
              type="button"
              className={`rounded px-2.5 py-1 text-xs font-medium ${
                state.previewMode === 'published' ? 'bg-primary-800 text-white' : 'text-primary-800 hover:bg-primary-100'
              }`}
              onClick={() => setPreviewMode('published')}
            >
              Published
            </button>
          </div>
        </div>

        <div className="flex min-w-0 flex-[1_1_10rem] justify-end">
          <button
            type="button"
            disabled={!isActiveDraftDirty}
            className="rounded-md bg-brand-400 px-3 py-1.5 text-xs font-semibold text-white shadow-sm transition-colors hover:bg-brand-600 disabled:cursor-not-allowed disabled:bg-primary-300 disabled:text-primary-600 disabled:shadow-none"
            onClick={() => setPublishOpen(true)}
          >
            Publish draft
          </button>
        </div>
      </div>

      {publishOpen ? (
        <div className="fixed inset-0 z-[200]">
          <TrustCenterModalBackdrop onClose={() => setPublishOpen(false)} />
          <div className="pointer-events-none absolute inset-0 flex items-center justify-center p-4">
            <div
              role="dialog"
              aria-modal="true"
              aria-labelledby="toolbar-publish-staging-title"
              className="pointer-events-auto w-full max-w-md rounded-lg border border-primary-400 bg-white p-6 shadow-xl"
            >
              <h2 id="toolbar-publish-staging-title" className="mb-2 text-base font-semibold text-primary-900">
                Publish to live Trust Center?
              </h2>
              <p className="mb-4 text-sm leading-relaxed text-primary-700">
                This copies the active draft to what visitors see on your public Trust Center (for example in another tab
                at{' '}
                <Link to="/trust-center" className="text-link-400 underline" target="_blank" rel="noreferrer">
                  /trust-center
                </Link>
                ). Staged areas: layout order, section visibility, brand colors, fonts, public view, Go Live, and logo and
                banner images.
              </p>
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  className="rounded border border-primary-400 px-3 py-1.5 text-sm font-medium text-primary-800 hover:bg-primary-100"
                  onClick={() => setPublishOpen(false)}
                >
                  Cancel
                </button>
                <button
                  type="button"
                  className="rounded bg-brand-400 px-3 py-1.5 text-sm font-medium text-white hover:bg-brand-600"
                  onClick={() => {
                    publishActiveDraft();
                    setPublishOpen(false);
                  }}
                >
                  Publish
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
}

