                          Share link
                        </button>
                      </div>
                    </>
                  ) : null}
                </div>
              </div>
              {detailOpen ? (
                <PublishedSnapshot
                  pub={pub}
                  liveLocaleLabels={includedLanguageLabels}
                  changelogNote={state.publishedChangelogNote}
                />
              ) : null}
            </div>
          </li>
        </ul>
      )}

