/**
 * TrustCenterAgentConfigurationSection
 * Draft right panel: Trust Center Ask AI Agent (sticky header + search). Values live on the draft snapshot.
 * Figma: Trust Center Vision HQ > Designer > Draft > Trust Center agent configuration
 */
import { useState } from 'react';
import { ChevronDown, ChevronUp } from 'lucide-react';
import { useDesigner } from '../../context/DesignerContext';
import { useTrustCenterCopy } from '../../hooks/useTrustCenterCopy';
import { mergeSavedAiAgentConfig } from '../../utils/stagingPresentation';

function AgentToggleRow({
  checked,
  onChange,
  label,
  description,
}: {
  checked: boolean;
  onChange: (next: boolean) => void;
  label: string;
  description: string;
}) {
  return (
    <div className="flex items-start justify-between gap-3 rounded-md border border-primary-200 bg-primary-100/40 px-3 py-2.5">
      <div className="min-w-0">
        <p className="text-xs font-medium text-primary-800">{label}</p>
        <p className="mt-0.5 text-[11px] leading-snug text-primary-600">{description}</p>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-label={label}
        onClick={() => onChange(!checked)}
        className={`relative mt-0.5 inline-flex h-3.5 w-[26px] shrink-0 items-center rounded-full transition-colors outline-none focus-visible:ring-2 focus-visible:ring-primary-800/25 ${
          checked ? 'bg-brand-400' : 'bg-primary-300'
        }`}
      >
        <span
          className={`pointer-events-none absolute top-1/2 h-[11px] w-[11px] -translate-y-1/2 rounded-full bg-white shadow-sm ${
            checked ? 'right-[1px]' : 'left-[1px]'
          }`}
        />
      </button>
    </div>
  );
}

export default function TrustCenterAgentConfigurationSection() {
  const { state, setSavedAiAgentConfig } = useDesigner();
  const copy = useTrustCenterCopy();
  const [expanded, setExpanded] = useState(true);
  const cfg = mergeSavedAiAgentConfig(state.savedAiAgentConfig);
  const defaultAskLabel = copy.sticky.askAiAgent;

  return (
    <div className="border-b border-primary-400">
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        aria-expanded={expanded}
        className="flex w-full items-center justify-between px-5 py-3 text-left"
      >
        <span className="text-sm font-medium text-primary-700">Trust Center agent configuration</span>
        {expanded ? (
          <ChevronUp size={14} className="text-primary-500" />
        ) : (
          <ChevronDown size={14} className="text-primary-500" />
        )}
      </button>
      {expanded ? (
        <div className="space-y-4 px-5 pb-4">
          <p className="text-[11px] leading-snug text-primary-600">
            Controls the Ask AI Agent control in the Trust Center header and Ask AI in search. Accent styling follows
            Brand Settings.
          </p>

          <AgentToggleRow
            checked={cfg.askAiEnabled}
            onChange={(next) => setSavedAiAgentConfig({ askAiEnabled: next })}
            label="Show Ask AI Agent"
            description="When off, the header button and Ask AI rows in search are hidden in this preview."
          />

          <div>
            <label htmlFor="tc-agent-button-label" className="mb-1 block text-xs font-medium text-primary-800">
              Button label
            </label>
            <p className="mb-1.5 text-[11px] leading-snug text-primary-600">Leave blank to use the default for the preview language.</p>
            <input
              id="tc-agent-button-label"
              type="text"
              value={cfg.buttonLabel}
              onChange={(e) => setSavedAiAgentConfig({ buttonLabel: e.target.value })}
              placeholder={defaultAskLabel}
              className="w-full rounded border border-primary-400 px-2.5 py-1.5 text-xs text-primary-800 placeholder-primary-500 focus:border-link-400 focus:outline-none focus:ring-1 focus:ring-link-400"
            />
          </div>

          <div>
            <label htmlFor="tc-agent-instructions" className="mb-1 block text-xs font-medium text-primary-800">
              Agent instructions
            </label>
            <p className="mb-1.5 text-[11px] leading-snug text-primary-600">
              Context for this Trust Center (prototype only, not wired to a live model).
            </p>
            <textarea
              id="tc-agent-instructions"
              rows={4}
              value={cfg.agentInstructions}
              onChange={(e) => setSavedAiAgentConfig({ agentInstructions: e.target.value })}
              placeholder="Example: Answer only from published documents and FAQs."
              className="w-full resize-y rounded border border-primary-400 px-2.5 py-2 text-xs text-primary-800 placeholder-primary-500 focus:border-link-400 focus:outline-none focus:ring-1 focus:ring-link-400"
            />
          </div>
        </div>
      ) : null}
    </div>
  );
}

